UPDATE product_sizes s JOIN products p ON p.id = s.product_id SET s.label = 'Half' WHERE p.slug = 'blueberry-cheesecake' AND s.label = 'Midi' AND NOT EXISTS (SELECT 1 FROM (SELECT s2.id FROM product_sizes s2 JOIN products p2 ON p2.id = s2.product_id WHERE p2.slug = 'blueberry-cheesecake' AND s2.label = 'Half') x);
DELETE s FROM product_sizes s JOIN products p ON p.id = s.product_id WHERE p.slug = 'blueberry-cheesecake' AND s.label NOT IN ('Full', 'Half');
